document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".carousel").forEach(function(e){var t=e.querySelector(".carousel-track"),n=e.querySelector(".carousel-prev"),s=e.querySelector(".carousel-next");n&&n.addEventListener("click",function(){t.scrollBy({left:-t.clientWidth,behavior:"smooth"})}),s&&s.addEventListener("click",function(){t.scrollBy({left:t.clientWidth,behavior:"smooth"})})})})